1	package pricing
2	
3	import (
4		"sort"
5	
6		"github.com/anthnel/devdesk/internal/agentusage"
7	)
8	
9	// noModelLabel names the bucket of tokens recorded under no model.
10	const noModelLabel = "(no model)"
11	
12	// Status tells what an Estimate holds.
13	type Status int
14	
15	const (
16		// NoTokens means there was nothing to price; USD is 0 and means nothing.
17		NoTokens Status = iota
18		// Priced means every model with tokens has a rate; USD is the cost.
19		Priced
20		// Unpriced means at least one model with tokens has no rate. USD is 0 and
21		// must not be shown: a partial sum would under-state without saying so.
22		Unpriced
23	)
24	
25	// Estimate is the indicative cost of an agent, or of a sum of agents.
26	type Estimate struct {
27		USD    float64
28		Status Status
29		// Unpriced lists the models with tokens and no rate, in first-appearance
30		// order; the bucket of no model is "(no model)".
31		Unpriced []string
32	}
33	
34	// Cost returns the cost in USD of one model's tokens. The 5 minute cache
35	// write is the total write minus its 1 hour part.
36	func (r Rates) Cost(m agentusage.ModelUsage) float64 {
37		t := m.Tokens
38		return (float64(t.Input)*r.Input +
39			float64(t.Output)*r.Output +
40			float64(m.CacheWrite5m())*r.CacheWrite5m +
41			float64(m.CacheWrite1h)*r.CacheWrite1h +
42			float64(t.CacheRead)*r.CacheRead) / perMillion
43	}
