1	// Package pricing turns the per-model token counts of internal/agentusage
2	// into an indicative cost in USD. It ships no price: the table is built from
3	// the user's configuration (agent_usage.prices), and a model without a rate
4	// has no cost rather than a zero one.
5	package pricing
6	
7	import (
8		"fmt"
9		"math"
10		"sort"
11		"strings"
12	
13		"github.com/anthnel/devdesk/internal/config"
14	)
15	
16	// perMillion is the token count a rate is quoted for.
17	const perMillion = 1_000_000.0
18	
19	// Rates is the price of one model, in USD per million tokens.
20	type Rates struct {
21		Input        float64
22		Output       float64
23		CacheWrite5m float64
24		CacheWrite1h float64
25		CacheRead    float64
26	}
27	
28	// Problem describes a price entry that was left out of the table. Key is the
29	// user's own spelling of the config key; Reason is meant for a log line.
30	type Problem struct {
31		Key    string
32		Reason string
33	}
34	
35	// Table maps normalized model names to their rates. The zero value is a
36	// valid empty table.
37	type Table struct {
38		rates map[string]Rates
39	}
40	
41	// Len returns the number of priced models.
42	func (t Table) Len() int { return len(t.rates) }
43	
44	// normalize makes a model name comparable: trimmed and lower case.
45	func normalize(s string) string { return strings.ToLower(strings.TrimSpace(s)) }
46	
47	// namedRate is one of the five rates of an entry, with its config key.
48	type namedRate struct {
49		name string
50		rate config.Rate
51		dst  *float64
52	}
53	
54	// FromConfig builds a Table from the configured prices. An entry that is
55	// incomplete, holds a rate that is not a finite non-negative number, or whose
56	// key collides with another after normalization is left out with a Problem;
57	// the other entries are unaffected. Problems are sorted by key.
58	func FromConfig(prices map[string]config.ModelPrice) (Table, []Problem) {
59		var problems []Problem
60		type candidate struct {
61			key   string
62			rates Rates
63		}
64		byNorm := map[string][]candidate{}
65	
66		for key, p := range prices {
67			norm := normalize(key)
68			if norm == "" {
69				problems = append(problems, Problem{Key: key, Reason: "empty model name"})
70				continue
71			}
72			r, reason := ratesOf(p)
73			if reason != "" {
74				problems = append(problems, Problem{Key: key, Reason: reason})
75				continue
76			}
77			byNorm[norm] = append(byNorm[norm], candidate{key: key, rates: r})
78		}
79	
80		t := Table{}
81		for norm, cs := range byNorm {
82			if len(cs) > 1 {
83				for _, c := range cs {
84					problems = append(problems, Problem{
85						Key:    c.key,
86						Reason: fmt.Sprintf("duplicate of another key once case and spaces are ignored (%q)", norm),
87					})
88				}
89				continue
90			}
91			if t.rates == nil {
92				t.rates = map[string]Rates{}
93			}
94			t.rates[norm] = cs[0].rates
95		}
96		sortProblems(problems)
97		return t, problems
98	}
99	
100	// ratesOf validates the five rates of an entry and returns them, or a reason
101	// naming the first rate that is unusable.
102	func ratesOf(p config.ModelPrice) (Rates, string) {
103		var r Rates
104		list := []namedRate{
105			{"input", p.Input, &r.Input},
106			{"output", p.Output, &r.Output},
107			{"cache_write_5m", p.CacheWrite5m, &r.CacheWrite5m},
108			{"cache_write_1h", p.CacheWrite1h, &r.CacheWrite1h},
109			{"cache_read", p.CacheRead, &r.CacheRead},
110		}
111		for _, nr := range list {
112			v, state := nr.rate.Value()
113			switch {
114			case state == config.RateMissing:
115				return Rates{}, "incomplete: missing " + nr.name
116			case state != config.RateSet:
117				return Rates{}, nr.name + " is not a number"
118			case math.IsNaN(v) || math.IsInf(v, 0):
119				return Rates{}, nr.name + " is not a finite number"
120			case v < 0:
121				return Rates{}, nr.name + " is negative"
122			}
123			*nr.dst = v
124		}
125		return r, ""
126	}
127	
128	func sortProblems(ps []Problem) {
129		sort.Slice(ps, func(i, j int) bool {
130			if ps[i].Key != ps[j].Key {
131				return ps[i].Key < ps[j].Key
132			}
133			return ps[i].Reason < ps[j].Reason
134		})
135	}
136

