3	// dateSuffixLen is the length of a trailing "-YYYYMMDD".
4	const dateSuffixLen = 9
5	
6	// Lookup returns the rates of a model. It matches the normalized name
7	// exactly, then once more without one trailing "-YYYYMMDD". There is no
8	// prefix matching, and nothing else is stripped ("[1m]", provider
9	// spellings): a key such as claude-sonnet-5 must never price
10	// claude-sonnet-5-5.
11	func (t Table) Lookup(model string) (Rates, bool) {
12		name := normalize(model)
13		if name == "" {
14			return Rates{}, false
15		}
16		if r, ok := t.rates[name]; ok {
17			return r, true
18		}
19		if base, ok := withoutDate(name); ok {
20			if r, ok := t.rates[base]; ok {
21				return r, true
22			}
23		}
24		return Rates{}, false
25	}
26	
27	// withoutDate removes one trailing "-" plus eight digits.
28	func withoutDate(name string) (string, bool) {
29		n := len(name)
30		if n <= dateSuffixLen || name[n-dateSuffixLen] != '-' {
31			return "", false
32		}
33		for i := n - dateSuffixLen + 1; i < n; i++ {
34			if name[i] < '0' || name[i] > '9' {
35				return "", false
36			}
37		}
38		return name[:n-dateSuffixLen], true
39	}
